from .formatting import format_payment
from .audit import record_audit
from .notify import notify_customer

def save_payment(payment):
    return {**payment, 'saved': True}

def process_payment(payment):
    saved = save_payment(payment)
    record_audit(format_payment(saved))
    notify_customer(saved)
    return saved

def checkout_payment(payment):
    return process_payment(payment)

